// [SKU MAP] one line per product, all maths in bottles, never packs
const SKU_MAP = {
  'B0EXAMPLE01': { sku: 'MAG-GLY-60', bottles_per_unit: 1, lead_time_days: 45 },
  'TT-MAG-2PK':  { sku: 'MAG-GLY-60', bottles_per_unit: 2, lead_time_days: 45 },
};
const rows = [];
const take = (name, source, pick) => {
  for (const it of $(name).all()) {
    for (const r of pick(it.json)) {
      const map = SKU_MAP[r.code];
      const flags = [];
      if (!map) flags.push('unmapped_sku');
      if (map && !map.lead_time_days) flags.push('missing_lead_time');
      if (r.expected_at === undefined) flags.push('missing_delivery_date');
      rows.push({
        source, code: r.code, sku: map ? map.sku : `UNMAPPED:${r.code}`,
        on_hand_bottles: (r.on_hand || 0) * (map ? map.bottles_per_unit : 1),
        inbound_bottles: (r.inbound || 0) * (map ? map.bottles_per_unit : 1),
        lead_time_days: map ? map.lead_time_days : null,
        flags,
      });
    }
  }
};
take('Amazon stock pulled (SP-API)', 'amazon', j => (j.payload?.inventorySummaries || []).map(s => ({ code: s.sellerSku, on_hand: s.inventoryDetails?.fulfillableQuantity, inbound: s.inventoryDetails?.inboundShippedQuantity })));
take('TikTok Shop stock pulled (Partner API)', 'tiktok', j => (j.data?.products || []).flatMap(p => (p.skus || []).map(s => ({ code: s.seller_sku, on_hand: (s.inventory || []).reduce((a, i) => a + (i.quantity || 0), 0), inbound: 0 }))));
take('Warehouse stock pulled (Jetpack)', 'jetpack', j => (j.items || []).map(i => ({ code: i.sku, on_hand: i.available, inbound: i.inbound, expected_at: i.expected_at })));
return rows.map(r => ({ json: r }));

// [RULES] moved line by line from the validated spreadsheet. Two examples:
//  1. days_of_cover = (on_hand + on_order) / daily_rate, red under lead_time + safety, amber under 1.5x that
//  2. demand_change = this week's rate vs last week's, flag over 25 percent either way
const SAFETY_DAYS = 14;          // editable by an admin later, not a code release
const DEMAND_CHANGE_FLAG = 0.25;
const rows = $('One SKU table, in bottles, gaps flagged').all().map(i => i.json);
// [DAILY SALES RATE] comes from the SP-API and TikTok sales reports in phase two; null until then
const rates = {};
const bySku = {};
for (const r of rows) {
  const s = bySku[r.sku] = bySku[r.sku] || { sku: r.sku, on_hand: 0, on_order: 0, lead_time_days: r.lead_time_days, flags: new Set(), sources: [] };
  s.on_hand += r.on_hand_bottles; s.on_order += r.inbound_bottles; s.sources.push(r.source);
  r.flags.forEach(f => s.flags.add(f));
}
const out = [];
for (const s of Object.values(bySku)) {
  const rate = rates[s.sku]; const reported = rate ? rate.reported_share : null;
  let status = 'grey', reason = 'unknown data, never green';
  if (rate && s.lead_time_days) {
    const cover = (s.on_hand + s.on_order) / rate.daily;
    const need = s.lead_time_days + SAFETY_DAYS;
    status = cover < need ? 'red' : cover < need * 1.5 ? 'amber' : 'green';
    reason = `${cover.toFixed(0)} days of cover vs ${need} needed`;
    if (rate.last_week && Math.abs(rate.daily - rate.last_week) / rate.last_week > DEMAND_CHANGE_FLAG) s.flags.add('demand_change');
  }
  out.push({ sku: s.sku, status, reason, trust: reported === null ? 'unknown' : `${Math.round(reported * 100)}% reported`, flags: [...s.flags], on_hand: s.on_hand, on_order: s.on_order });
}
const alerts = out.filter(o => o.status === 'red' || o.status === 'amber');
const health = out.filter(o => o.flags.length);
return [{ json: {
  date: new Date().toISOString().slice(0, 10),
  checked: out.length, alert_count: alerts.length,
  reds: alerts.filter(a => a.status === 'red').map(a => `${a.sku} (${a.reason}, trust ${a.trust})`),
  ambers: alerts.filter(a => a.status === 'amber').map(a => `${a.sku} (${a.reason}, trust ${a.trust})`),
  greys: out.filter(o => o.status === 'grey').map(o => o.sku),
  unmapped: health.filter(h => h.flags.includes('unmapped_sku')).map(h => h.sku),
  missing_lead_time: health.filter(h => h.flags.includes('missing_lead_time')).map(h => h.sku),
  missing_delivery_date: health.filter(h => h.flags.includes('missing_delivery_date')).map(h => h.sku),
  demand_change: out.filter(o => o.flags.includes('demand_change')).map(o => o.sku),
} }];

